1	import { copyFile, mkdir, mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
2	import { tmpdir } from 'node:os';
3	import { basename, dirname, join } from 'node:path';
4	import { pathToFileURL } from 'node:url';
5	import type { HarnessDefaults, ModelCatalogEntry } from '@graphgoblin/contracts';
6	import { FakeHarness } from '@graphgoblin/engine/testing';
7	import {
8	  DEFAULT_MODEL_CATALOG,
9	  SqliteModelCatalog,
10	  databaseView,
11	  openDatabase,
12	  openReadOnlyDatabaseClient,
13	} from '@graphgoblin/infrastructure/sqlite';
14	import { afterEach, beforeEach, describe, expect, it } from 'vitest';
15	import { loadConfig } from './config.js';
16	import { createContainer } from './container.js';
17	import { runPreflightCli } from './preflight.js';
18	
19	const KEY = Buffer.alloc(32, 8).toString('base64');
20	let dir: string;
21	
22	beforeEach(async () => {
23	  dir = await mkdtemp(join(tmpdir(), 'gg-preflight-catalog-'));
24	});
25	
26	afterEach(async () => {
27	  globalThis.gc?.();
28	  await rm(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 100 });
29	});
30	
31	function adapters() {
32	  return {
33	    harnesses: { codex: new FakeHarness(), claude: new FakeHarness([], 'claude') },
34	    deciders: [],
35	    startTimers: false,
36	  };
37	}
38	
39	function env(dbFile: string, defaults: HarnessDefaults): Record<string, string> {
40	  return {
41	    GG_DATA_DIR: join(dir, 'data'),
42	    GG_DB_URL: pathToFileURL(dbFile).href,
43	    GG_MASTER_KEY: KEY,
44	    GG_DEFAULTS: JSON.stringify(defaults),
45	  };
46	}
47	
48	async function cli(environment: Record<string, string>) {
49	  let out = '';
50	  const code = await runPreflightCli({
51	    env: environment,
52	    ...adapters(),
53	    write: (text) => {
54	      out += text;
55	    },
56	  });
57	  return { code, out };
58	}
59	
60	async function fixture(dbFile: string, rows = DEFAULT_MODEL_CATALOG) {
61	  await mkdir(dirname(dbFile), { recursive: true });
62	  const handle = openDatabase({ url: pathToFileURL(dbFile).href });
63	  try {
64	    await handle.migrate();
65	    await new SqliteModelCatalog(handle.db).seed(rows);
66	    await handle.client.execute('PRAGMA wal_checkpoint(TRUNCATE)');
67	  } finally {
68	    handle.close();
69	  }
70	}
71	
72	/** SQLite readers update -shm read marks; only DB/WAL contain the stored data. */
73	async function storeBytes(dbFile: string) {
74	  const names = (await readdir(dirname(dbFile))).filter(
75	    (name) => name === basename(dbFile) || name === `${basename(dbFile)}-wal`,
76	  );
77	  return Object.fromEntries(
78	    await Promise.all(
79	      names.map(async (name): Promise<[string, Buffer]> => [
80	        name,
81	        await readFile(join(dirname(dbFile), name)),
82	      ]),
83	    ),
84	  );
85	}
86	
87	async function storedCatalog(dbFile: string) {
88	  const client = openReadOnlyDatabaseClient(dbFile);
89	  try {
90	    return await new SqliteModelCatalog(databaseView(client)).list();
91	  } finally {
92	    client.close();
93	  }
94	}
95	
96	describe('offline startup catalog admission', () => {
97	  it.each([
98	    ['codex', 'gpt-6.1-terra', 'medium'],
99	    ['claude', 'claude-opus-5-5', 'high'],
100	  ] as const)(
101	    'accepts a missing shipped %s seed without storing it',
102	    async (harness, model, effort) => {
103	      // The DB is outside GG_DATA_DIR and its URL is percent-encoded: both paths use startup's
104	      // projected catalog. This simulates a current-format store before its first upgrade start.
105	      const dbFile = join(dir, 'external store', 'gateway.db');
106	      await fixture(
107	        dbFile,
108	        DEFAULT_MODEL_CATALOG.filter(
109	          (entry) => !(entry.harness === harness && entry.model === model),
110	        ),
111	      );
112	      const defaults: HarnessDefaults = {
113	        byHarness: { codex: { model: 'gpt-6-luna', effort: 'low' }, [harness]: { model, effort } },
114	      };
115	      const environment = env(dbFile, defaults);
116	      const before = await storeBytes(dbFile);
117	      const report = await cli(environment);
118	      expect(report.code, report.out).toBe(0);
119	      expect(report.out).toMatch(/ok\s+Database\s+reachable and migrated/);
120	      expect(report.out).toMatch(
121	        harness === 'codex'
122	          ? /ok\s+Default model\s+gpt-6.1-terra \(codex\) is in the model catalog/
123	          : /ok\s+Claude default model\s+Exact Claude model and effort are configured/,
124	      );
125	      expect(await storeBytes(dbFile)).toEqual(before);
126	      expect(
127	        (await storedCatalog(dbFile)).some((row) => row.harness === harness && row.model === model),
128	      ).toBe(false);
129	      await expect(readdir(environment['GG_DATA_DIR']!)).rejects.toMatchObject({ code: 'ENOENT' });
130	
131	      const container = await createContainer(loadConfig(environment), adapters());
132	      try {
133	        await container.start();
134	        expect(await container.repos.catalog.findOne(harness, model)).toMatchObject({
135	          enabled: true,
136	        });
137	      } finally {
138	        await container.stop();
139	      }
140	    },
141	  );
142	
143	  it.each([
144	    {
145	      harness: 'codex',
146	      model: 'gpt-6.1-terra',
147	      effort: 'medium',
148	      enabled: false,
149	      status: 'WARN',
150	      code: 0,
151	      refusal: undefined,
152	    },
153	    {
154	      harness: 'claude',
155	      model: 'claude-opus-5-5',
156	      effort: 'high',
157	      enabled: false,
158	      status: 'FAIL',
159	      code: 1,
160	      refusal: undefined,
161	    },
162	    {
163	      harness: 'codex',
164	      model: 'unknown-model',
165	      effort: 'low',
166	      status: 'FAIL',
167	      code: 1,
168	      refusal: 'MODEL_NOT_IN_CATALOG',
169	    },
170	    {
171	      harness: 'codex',
172	      model: 'claude-opus-5-5',
173	      effort: 'high',
174	      status: 'FAIL',
175	      code: 1,
176	      refusal: 'MODEL_HARNESS_MISMATCH',
177	    },
178	    {
179	      harness: 'claude',
180	      model: 'gpt-6-luna',
181	      effort: 'low',
182	      status: 'FAIL',
183	      code: 1,
184	      refusal: 'MODEL_HARNESS_MISMATCH',
185	    },
186	    {
187	      harness: 'claude',
188	      model: 'claude-opus-5-5',
189	      effort: 'none',
190	      status: 'FAIL',
191	      code: 1,
192	      refusal: 'EFFORT_UNSUPPORTED',
193	    },
194	    {
195	      harness: 'claude',
196	      model: 'claude-opus-5-5',
197	      effort: 'low',
198	      efforts: ['high'],
199	      status: 'FAIL',
200	      code: 1,
201	      refusal: 'EFFORT_UNSUPPORTED',
202	    },
203	    // Codex preflight currently checks membership/enabled, while startup also checks effort.
204	    {
205	      harness: 'codex',
206	      model: 'gpt-5.5',
207	      effort: 'none',
208	      status: 'ok',
209	      code: 0,
210	      refusal: 'EFFORT_UNSUPPORTED',
211	    },
212	  ] as const)(
213	    'preserves $harness $model defaults (effort=$effort, status=$status)',
214	    async (test) => {
215	      const dbFile = join(dir, 'gateway.db');
216	      const rows: ModelCatalogEntry[] = DEFAULT_MODEL_CATALOG.map((entry) =>
217	        entry.harness === test.harness && entry.model === test.model
218	          ? {
219	              ...entry,
220	              ...('enabled' in test ? { enabled: test.enabled } : {}),
221	              ...('efforts' in test ? { efforts: [...test.efforts] } : {}),
222	            }
223	          : entry,
224	      );
225	      await fixture(dbFile, rows);
226	      const defaults: HarnessDefaults = {
227	        byHarness: {
228	          codex: { model: 'gpt-6-luna', effort: 'low' },
229	          [test.harness]: { model: test.model, effort: test.effort },
230	        },
231	      };
232	      const environment = env(dbFile, defaults);
233	      const before = await storeBytes(dbFile);
234	      const report = await cli(environment);
235	      expect(report.code, report.out).toBe(test.code);
