1	import { readinessDetail, readinessMessage } from '@graphgoblin/domain';
2	import { randomUUID } from 'node:crypto';
3	import { open, readFile, stat, unlink } from 'node:fs/promises';
4	import { dirname, join } from 'node:path';
5	import { OllamaHarness } from '@graphgoblin/infrastructure/ollama';
6	import { ClaudeHarness } from '@graphgoblin/infrastructure/claude';
7	import { createCodexAdapters } from '@graphgoblin/adapter-codex';
8	import {
9	  HarnessReadinessStateSchema,
10	  OllamaConnectionSchema,
11	  type OllamaConnection,
12	  type HarnessId,
13	} from '@graphgoblin/contracts';
14	import type { HarnessPort } from '@graphgoblin/engine';
15	import {
16	  DEFAULT_MODEL_CATALOG,
17	  SqliteModelCatalog,
18	  SqliteClassifierModels,
19	  SqliteSecrets,
20	  UnsupportedStoreError,
21	  databaseFilePath,
22	  databaseView,
23	  guardCurrentStore,
24	  openDatabase,
25	  openReadOnlyDatabaseClient,
26	  pendingMigrationCount,
27	  projectStartupModelCatalog,
28	  type Database,
29	  type ModelCatalogEntry,
30	} from '@graphgoblin/infrastructure/sqlite';
31	import { z } from 'zod';
32	import { loadConfig, type ApiConfig } from './config.js';
33	import { JEV_SECRET, LOCAL_OWNER, type Container } from './container.js';
34	import { dataDirArgument, RESET_COMMAND } from './store-refusal.js';
35	
36	/**
37	 * First-run preflight (docs/11): is this machine ready to run GraphGoblin? Each check reports
38	 * `ok`, `warn` (works, but something is missing or will be set up on first start), or `fail`
39	 * (runs will not work until it is fixed). Served at `GET /system/preflight` and printed by
40	 * `graphgoblin-api --preflight`. Nothing here spawns a Codex session or changes any state.
41	 */
42	
43	export const PreflightStatusSchema = z.enum(['ok', 'warn', 'fail']);
44	export type PreflightStatus = z.infer<typeof PreflightStatusSchema>;
45	
46	export const PreflightCheckSchema = z.object({
47	  state: HarnessReadinessStateSchema.optional(),
48	  id: z.string(),
49	  label: z.string(),
50	  status: PreflightStatusSchema,
51	  message: z.string(),
52	});
53	export type PreflightCheck = z.infer<typeof PreflightCheckSchema>;
54	
55	export const PreflightReportSchema = z.object({
56	  /** False when any check failed. Warnings do not make the report fail. */
57	  ok: z.boolean(),
58	  checks: z.array(PreflightCheckSchema),
59	});
60	export type PreflightReport = z.infer<typeof PreflightReportSchema>;
61	
62	export const SUPPORTED_NODE_MAJOR = 22;
63	
64	/** Where the checks read their facts from: the running container, or the configuration alone. */
65	export interface PreflightSources {
66	  config: ApiConfig;
67	  /** Default: `process.versions.node`. */
68	  nodeVersion?: string;
69	  harnesses: Partial<Record<HarnessId, HarnessPort>>;
70	  /** CLI cannot inspect saved connection settings until its existing store is current. */
71	  ollamaDeferredReason?: string;
72	  /** Migrations still to apply, or `'missing'` when the database file does not exist yet. Throws when unreachable. */
73	  pendingMigrations(): Promise<number | 'missing'>;
74	  /** The Jev API key, if set. Only called once the database is migrated. */
75	  jevKey(): Promise<string | undefined>;
76	  /** Built-in catalog availability; no provider call. Only read after migration. */
77	  jevEnabled(): Promise<boolean>;
78	  /** The model catalog. Only called once the database is migrated. */
79	  catalog(): Promise<ModelCatalogEntry[]>;
80	}
81	
82	function message(error: unknown): string {
83	  return error instanceof Error ? error.message : String(error);
84	}
85	
86	function check(id: string, label: string, status: PreflightStatus, text: string): PreflightCheck {
87	  return { id, label, status, message: text };
88	}
89	
90	export function checkNode(version: string): PreflightCheck {
91	  const major = Number(/^v?(\d+)/.exec(version)?.[1] ?? NaN);
92	  return major === SUPPORTED_NODE_MAJOR
93	    ? check('node', 'Node.js', 'ok', `Node ${version}`)
94	    : check(
95	        'node',
96	        'Node.js',
97	        'fail',
98	        `Node ${version} is unsupported; GraphGoblin needs Node ${String(SUPPORTED_NODE_MAJOR)} LTS. Select Node ${String(SUPPORTED_NODE_MAJOR)} on PATH`,
99	      );
100	}
101	
102	/** A fresh probe file name; random, so concurrent preflights never share one. */
103	export type ProbeName = () => string;
104	const defaultProbeName: ProbeName = () => `.preflight-${randomUUID()}`;
105	
106	/**
107	 * Prove `dir` is writable by creating a new file in it exclusively (`wx`: never truncates an
108	 * existing file and never follows a symlink at that path) and removing only that file. A name
109	 * that already exists is skipped for the next one. Throws when the directory is not writable.
110	 */
111	export async function probeWritable(
112	  dir: string,
113	  name: ProbeName = defaultProbeName,
114	): Promise<void> {
115	  for (let attempt = 0; ; attempt += 1) {
116	    const path = join(dir, name());
117	    let handle;
118	    try {
119	      handle = await open(path, 'wx');
120	    } catch (error) {
121	      if ((error as NodeJS.ErrnoException).code === 'EEXIST' && attempt < 4) continue;
122	      throw error;
123	    }
124	    await handle.close();
125	    await unlink(path);
126	    return;
127	  }
128	}
129	
130	export async function checkDataDir(
131	  dir: string,
132	  probeName: ProbeName = defaultProbeName,
133	): Promise<PreflightCheck> {
134	  const fail = (text: string): PreflightCheck => check('data-dir', 'Data directory', 'fail', text);
135	  let isDirectory: boolean;
136	  try {
137	    isDirectory = (await stat(dir)).isDirectory();
138	  } catch (error) {
139	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
140	      return check(
141	        'data-dir',
142	        'Data directory',
143	        'warn',
144	        `${dir} does not exist yet; it is created on first start`,
145	      );
146	    }
147	    return fail(`cannot read ${dir}: ${message(error)}`);
148	  }
149	  if (!isDirectory) return fail(`${dir} exists but is not a directory`);
150	  try {
151	    await probeWritable(dir, probeName);
152	  } catch (error) {
153	    return fail(`${dir} is not writable: ${message(error)}`);
154	  }
155	  return check('data-dir', 'Data directory', 'ok', `${dir} is writable`);
156	}
157	
158	/** Read the master key the way `loadMasterKey` does, without generating one. */
159	export async function readMasterKey(
160	  config: Pick<ApiConfig, 'dataDir' | 'masterKey'>,
161	): Promise<{ check: PreflightCheck; key?: Buffer }> {
162	  const result = (status: PreflightStatus, text: string, key?: Buffer) => ({
163	    check: check('master-key', 'Master key', status, text),
164	    ...(key ? { key } : {}),
165	  });
166	  if (config.masterKey) {
167	    const key = Buffer.from(config.masterKey, 'base64');
168	    return key.length === 32
169	      ? result('ok', 'taken from GG_MASTER_KEY', key)
170	      : result('fail', 'GG_MASTER_KEY must be base64 for exactly 32 bytes');
171	  }
172	  const file = join(config.dataDir, 'master.key');
173	  let text: string;
174	  try {
175	    text = await readFile(file, 'utf8');
176	  } catch (error) {
177	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
178	      return result(
179	        'warn',
180	        `${file} does not exist yet; a key is generated on first start (back it up, or set GG_MASTER_KEY)`,
181	      );
182	    }
183	    return result('fail', `cannot read ${file}: ${message(error)}`);
184	  }
185	  const key = Buffer.from(text.trim(), 'base64');
186	  return key.length === 32
187	    ? result('ok', `read from ${file}`, key)
188	    : result('fail', `${file} does not contain a base64 32-byte key`);
189	}
190	
191	async function checkHarnesses(
192	  harnesses: Partial<Record<HarnessId, HarnessPort>>,
193	  config: ApiConfig,
194	  ollamaDeferredReason?: string,
195	): Promise<PreflightCheck[]> {
196	  const checks: PreflightCheck[] = [];
197	  await Promise.all(
198	    Object.entries(harnesses).map(async ([id, harness]) => {
199	      if (!harness) return;
200	      const label = `Harness ${id}`;
201	      if (id === 'ollama' && ollamaDeferredReason) {
202	        checks.push({
203	          state: 'unknown',
204	          ...check('harness.ollama', label, 'warn', ollamaDeferredReason),
205	        });
206	        return;
207	      }
208	      const unavailableStatus =
209	        (id === 'claude' && !config.defaults.byHarness.claude) ||
210	        (id === 'ollama' && config.defaults.byHarness.ollama?.model === undefined) ||
211	        (id === 'codex' && ollamaOnly(config))
212	          ? ('warn' as const)
213	          : ('fail' as const);
214	      try {
215	        const result = await harness.preflight();
216	        const version = result.version ? ` ${result.version}` : '';
217	        checks.push({
218	          state: result.state,
219	          ...(result.ok
220	            ? check(
221	                `harness.${id}`,
222	                label,
223	                'ok',
224	                id === 'ollama'
225	                  ? readinessDetail('ollama', 'ready')
226	                  : `${id}${version} is installed and logged in`,
227	              )
228	            : check(
229	                `harness.${id}`,
230	                label,
231	                unavailableStatus,
232	                result.problems.join(' ') || readinessMessage(id, result.state),
233	              )),
234	        });
235	      } catch {
236	        checks.push({
237	          state: 'unknown',
238	          ...check(`harness.${id}`, label, unavailableStatus, readinessMessage(id, 'unknown')),
239	        });
240	      }
241	    }),
242	  );
243	  if (ollamaOnly(config) && !harnesses.codex)
244	    checks.push(
245	      check(
246	        'harness.codex',
247	        'Harness codex',
248	        'warn',
249	        'Codex is optional for the configured Ollama-only defaults',
250	      ),
251	    );
252	  if (checks.length === 0) {
253	    checks.push(check('harness', 'Harness', 'fail', 'no harness adapter is configured'));
254	  }
255	  return checks;
256	}
257	
258	function ollamaOnly(config: ApiConfig): boolean {
259	  return (
260	    config.defaults.byHarness.ollama?.model !== undefined &&
261	    config.defaults.byHarness.codex === undefined
262	  );
263	}
264	
265	function checkDefaultModel(
266	  model: string | undefined,
267	  catalog: ModelCatalogEntry[],
268	  seeded: boolean,
269	): PreflightCheck {
270	  const entry = catalog.find((e) => e.harness === 'codex' && e.model === model);
271	  const where = seeded ? 'the model catalog' : 'the default catalog seeded on first start';
272	  if (!entry) {
273	    return check(
274	      'default-model',
275	      'Default model',
276	      'fail',
277	      `GG_DEFAULTS.byHarness.codex.model "${model}" is not in ${where}; pick a listed harness model and enable it in Settings`,
278	    );
279	  }
280	  if (!entry.enabled) {
281	    return check('default-model', 'Default model', 'warn', `${model} is in ${where} but disabled`);
282	  }
283	  return check(
284	    'default-model',
285	    'Default model',
286	    'ok',
287	    `${model} (${entry.harness}) is in ${where}`,
288	  );
289	}
290	
291	/** Run every check. Never throws: a check that cannot run reports `fail` with the reason. */
292	export async function runPreflight(sources: PreflightSources): Promise<PreflightReport> {
293	  const { config } = sources;
294	  const checks: PreflightCheck[] = [checkNode(sources.nodeVersion ?? process.versions.node)];
295	  checks.push(await checkDataDir(config.dataDir));
296	  checks.push((await readMasterKey(config)).check);
297	
298	  let migrated = false;
299	  try {
300	    const pending = await sources.pendingMigrations();
301	    if (pending === 'missing') {
302	      checks.push(
303	        check(
304	          'database',
305	          'Database',
306	          'warn',
307	          'the database does not exist yet; it is created and migrated on first start',
308	        ),
309	      );
310	    } else if (pending > 0) {
311	      checks.push(
312	        check(
313	          'database',
314	          'Database',
315	          'warn',
316	          `${String(pending)} migration(s) pending; they are applied on the next start`,
317	        ),
318	      );
319	    } else {
320	      migrated = true;
321	      checks.push(check('database', 'Database', 'ok', 'reachable and migrated'));
322	    }
323	  } catch (error) {
324	    checks.push(
325	      check(
326	        'database',
327	        'Database',
328	        'fail',
329	        error instanceof UnsupportedStoreError
330	          ? `${error.reason}. Start refuses this store and converts nothing; to start fresh, list what a reset removes with ${RESET_COMMAND} ${dataDirArgument(config.dataDir)}`
331	          : `not reachable: ${message(error)}`,
332	      ),
333	    );
334	  }
335	
336	  checks.push(...(await checkHarnesses(sources.harnesses, config, sources.ollamaDeferredReason)));
337	
338	  if (!migrated) {
339	    checks.push(
340	      check('jev', 'Jev', 'warn', 'not checked until the database is migrated; Jev is optional'),
341	    );
342	  } else {
343	    try {
344	      const key = (await sources.jevKey())?.trim();
345	      checks.push(
346	        key
347	          ? check(
348	              'jev',
349	              'Jev',
350	              'ok',
351	              `API key set (secret "${JEV_SECRET}")${(await sources.jevEnabled()) ? '' : ' (disabled in Settings)'}`,
352	            )
353	          : check(
354	              'jev',
355	              'Jev',
356	              'warn',
357	              `no API key in secret "${JEV_SECRET}"; Jev is optional; its classifier is unavailable until a key is configured`,
358	            ),
359	      );
360	    } catch (error) {
361	      checks.push(check('jev', 'Jev', 'warn', `cannot read the Jev key: ${message(error)}`));
362	    }
363	  }
364	
365	  try {
366	    const catalog = migrated ? await sources.catalog() : DEFAULT_MODEL_CATALOG;
367	    if (!ollamaOnly(config))
368	      checks.push(checkDefaultModel(config.defaults.byHarness.codex?.model, catalog, migrated));
369	    const ollama = config.defaults.byHarness.ollama;
370	    if (ollama?.model !== undefined) {
371	      const entry = catalog.find((row) => row.harness === 'ollama' && row.model === ollama.model);
372	      if (!migrated || !entry)
373	        checks.push(
374	          check(
375	            'default-model.ollama',
376	            'Ollama default model',
377	            'warn',
378	            'The configured Ollama model is not checked until discovery',
379	          ),
380	        );
381	      else {
382	        const problem =
383	          entry.availability && entry.availability.state !== 'available'
384	            ? (entry.availability.reason ??
385	              'The configured Ollama model is unavailable; refresh models in Settings')
386	            : !entry.enabled
387	              ? 'The configured Ollama model is disabled'
388	              : !ollama.effort || !entry.efforts.includes(ollama.effort)
389	                ? 'Configure an explicit supported Ollama thinking control'
390	                : undefined;
391	        checks.push(
392	          check(
393	            'default-model.ollama',
394	            'Ollama default model',
395	            problem ? 'fail' : 'ok',
396	            problem ?? 'Exact Ollama model and effort are configured and available',
397	          ),
398	        );
399	      }
400	      if (!sources.harnesses.ollama && !sources.ollamaDeferredReason)
401	        checks.push(
402	          check(
403	            'harness.ollama',
404	            'Harness ollama',
405	            'fail',
406	            'The configured Ollama harness is unavailable',
407	          ),
408	        );
409	    }
410	    const defaults = config.defaults.byHarness.claude;
411	    if (defaults) {
412	      const entry = catalog.find((row) => row.harness === 'claude' && row.model === defaults.model);
413	      const problem = !entry
414	        ? 'The configured Claude model is not in the catalog'
415	        : !defaults.effort || !entry.efforts.includes(defaults.effort)
416	          ? 'Configure an explicit supported Claude reasoning effort'
417	          : !entry.enabled
418	            ? 'The configured Claude model is disabled'
419	            : undefined;
420	      checks.push(
421	        check(
422	          'default-model.claude',
423	          'Claude default model',
424	          problem ? 'fail' : 'ok',
425	          problem ?? 'Exact Claude model and effort are configured',
426	        ),
427	      );
428	      if (!sources.harnesses.claude)
429	        checks.push(
430	          check(
431	            'harness.claude',
432	            'Harness claude',
433	            'fail',
434	            'The configured Claude harness is unavailable',
435	          ),
436	        );
437	    }
438	  } catch (error) {
439	    checks.push(
440	      check('default-model', 'Default model', 'fail', `cannot read the catalog: ${message(error)}`),
441	    );
442	  }
443	
444	  return { ok: checks.every((c) => c.status !== 'fail'), checks };
445	}
446	
447	/** Facts from a running container, for `GET /system/preflight`. */
448	export function containerPreflightSources(container: Container): PreflightSources {
449	  return {
450	    config: container.config,
451	    harnesses: container.ports.harnesses,
452	    pendingMigrations: () => container.handle.pendingMigrations(),
453	    jevKey: () => container.repos.secretsFor(LOCAL_OWNER).resolve(JEV_SECRET),
454	    jevEnabled: async () =>
455	      (await container.repos.classifiers.findOne(LOCAL_OWNER, 'jev'))?.enabled ?? true,
456	    catalog: () => container.repos.catalog.list(),
457	  };
458	}
459	
460	function isMissing(error: unknown): boolean {
461	  return (error as NodeJS.ErrnoException).code === 'ENOENT';
462	}
463	
464	/**
465	 * Whether the server's start can create `file`: it creates the missing directories above it, so
466	 * the nearest existing ancestor must be a writable directory. Throws with the reason otherwise.
467	 */
468	export async function assertCreatable(file: string, probeName?: ProbeName): Promise<void> {
469	  let dir = dirname(file);
470	  for (;;) {
471	    let isDirectory: boolean;
472	    try {
473	      isDirectory = (await stat(dir)).isDirectory();
474	    } catch (error) {
475	      if (!isMissing(error) || dirname(dir) === dir) throw error;
476	      dir = dirname(dir);
477	      continue;
478	    }
479	    if (!isDirectory) throw new Error(`${file} cannot be created: ${dir} is not a directory`);
480	    try {
481	      await probeWritable(dir, probeName);
482	    } catch (error) {
483	      throw new Error(`${file} cannot be created: ${dir} is not writable (${message(error)})`, {
484	        cause: error,
485	      });
486	    }
487	    return;
488	  }
489	}
490	
491	/** The connection preflight inspects a store through: read-only for a file on disk. */
492	interface InspectedDatabase {
493	  client: ReturnType<typeof openReadOnlyDatabaseClient>;
494	  db: Database;
495	  pendingMigrations(): Promise<number>;
496	  close(): void;
497	}
498	
499	/** What the CLI can learn about the database before the server has started. */
500	type DatabaseState =
501	  | { kind: 'missing' }
502	  | { kind: 'broken'; error: unknown }
503	  | { kind: 'open'; handle: InspectedDatabase };
504	
505	async function inspectDatabase(url: string): Promise<DatabaseState> {
506	  const file = databaseFilePath(url);
507	  if (file !== undefined) {
508	    try {
509	      await stat(file);
510	    } catch (error) {
511	      if (!isMissing(error)) return { kind: 'broken', error };
512	      try {
513	        await assertCreatable(file);
514	        return { kind: 'missing' };
515	      } catch (reason) {
516	        return { kind: 'broken', error: reason };
517	      }
518	    }
519	  }
520	  try {
521	    if (file !== undefined) {
522	      // The same read-only connection as startup's guard: a refused or healthy store keeps its
523	      // database and write-ahead log bytes (a mutable connection checkpoints the log on close).
524	      const client = openReadOnlyDatabaseClient(file);
525	      return {
526	        kind: 'open',
527	        handle: {
528	          client,
529	          db: databaseView(client),
530	          pendingMigrations: () => pendingMigrationCount(client),
531	          close: () => client.close(),
532	        },
533	      };
534	    }
535	    return { kind: 'open', handle: openDatabase({ url }) };
536	  } catch (error) {
537	    return { kind: 'broken', error };
538	  }
539	}
540	
541	/** Never initializes the singleton or guesses over saved settings in an unverified store. */
542	async function inspectedOllamaConnection(
543	  database: DatabaseState,
544	  config: ApiConfig,
545	): Promise<
546	  | { connection: OllamaConnection; deferredReason?: never }
547	  | { connection?: never; deferredReason: string }
548	> {
549	  const fallback = { enabled: config.ollamaEnabled, baseUrl: config.ollamaUrl, revision: 1 };
550	  if (database.kind === 'missing') return { connection: fallback };
551	  if (database.kind === 'broken')
552	    return { deferredReason: 'Ollama is not checked until the database can be read' };
553	  try {
554	    await guardCurrentStore(database.handle.client);
555	    if ((await database.handle.pendingMigrations()) !== 0)
556	      return { deferredReason: 'Ollama is not checked until the database is migrated' };
557	    const row = await database.handle.db.query.ollamaConnection.findFirst({
558	      where: (row, { eq }) => eq(row.id, 'gateway'),
559	    });
560	    return {
561	      connection: row
562	        ? OllamaConnectionSchema.parse({
563	            enabled: row.enabled,
564	            baseUrl: row.baseUrl,
565	            revision: row.revision,
566	          })
567	        : fallback,
568	    };
569	  } catch {
570	    return { deferredReason: 'Ollama is not checked until the database is current and readable' };
571	  }
572	}
573	
574	export interface ConfigPreflightOptions {
575	  /** Replace the native harness map (tests). */
576	  harnesses?: Partial<Record<HarnessId, HarnessPort>>;
577	  nodeVersion?: string;
578	}
579	
580	/**
581	 * Facts from the configuration alone, for the CLI before the server has started. Opens the
582	 * database only when its file exists, so a first run creates nothing; a missing file is a
583	 * warning only when the server's start could create it.
584	 */
585	export async function configPreflightSources(
586	  config: ApiConfig,
587	  options: ConfigPreflightOptions = {},
588	): Promise<PreflightSources & { close(): void }> {
589	  const database = await inspectDatabase(config.dbUrl);
590	  const { key } = await readMasterKey(config);
591	  const ollama = await inspectedOllamaConnection(database, config);
592	  const harnesses = options.harnesses ?? {
593	    codex: createCodexAdapters({
594	      ...(config.defaults.byHarness.codex?.model !== undefined
595	        ? { model: config.defaults.byHarness.codex.model }
596	        : {}),
597	      ...(config.defaults.byHarness.codex?.effort !== undefined
598	        ? { effort: config.defaults.byHarness.codex.effort }
599	        : {}),
600	      ...(config.codexBinary ? { codexBinary: config.codexBinary } : {}),
601	    }).harness,
602	    claude: new ClaudeHarness({ ...(config.claudeBinary ? { binary: config.claudeBinary } : {}) }),
603	    ollama: new OllamaHarness({
604	      snapshot: () =>
605	        ollama.connection
606	          ? Promise.resolve({ connection: ollama.connection, models: [] })
607	          : Promise.reject(new Error(ollama.deferredReason)),
608	    }),
609	  };
610	  const base = {
611	    config,
612	    harnesses,
613	    ...(ollama.deferredReason ? { ollamaDeferredReason: ollama.deferredReason } : {}),
614	    ...(options.nodeVersion ? { nodeVersion: options.nodeVersion } : {}),
615	  };
616	  if (database.kind !== 'open') {
617	    const { kind } = database;
618	    const failure = kind === 'broken' ? database.error : undefined;
619	    return {
620	      ...base,
621	      pendingMigrations: () =>
622	        kind === 'missing'
623	          ? Promise.resolve('missing' as const)
624	          : Promise.reject(failure instanceof Error ? failure : new Error(String(failure))),
625	      jevKey: () => Promise.resolve(undefined),
626	      jevEnabled: () => Promise.resolve(true),
627	      catalog: () => Promise.resolve(DEFAULT_MODEL_CATALOG),
628	      close: () => undefined,
629	    };
630	  }
631	  const { handle } = database;
632	  return {
633	    ...base,
634	    // A store start would refuse is reported as such, never as migrations it would apply.
635	    pendingMigrations: async () => {
636	      await guardCurrentStore(handle.client);
637	      return handle.pendingMigrations();
638	    },
639	    jevKey: () =>
640	      key
641	        ? new SqliteSecrets(handle.db, { now: () => new Date() }, key, LOCAL_OWNER).resolve(
642	            JEV_SECRET,
643	          )
644	        : Promise.resolve(undefined),
645	    catalog: async () => projectStartupModelCatalog(await new SqliteModelCatalog(handle.db).list()),
646	    jevEnabled: async () =>
647	      (await new SqliteClassifierModels(handle.db).findOne(LOCAL_OWNER, 'jev'))?.enabled ?? true,
648	    close: () => handle.close(),
649	  };
650	}
651	
652	const MARK: Record<PreflightStatus, string> = { ok: 'ok', warn: 'WARN', fail: 'FAIL' };
653	
654	/** A plain-text table for the terminal. */
655	export function formatPreflight(report: PreflightReport): string {
656	  const rows = report.checks.map((c) => [MARK[c.status], c.label, c.message] as const);
657	  const width = (i: 0 | 1, title: string) =>
658	    Math.max(title.length, ...rows.map((r) => r[i].length));
659	  const w0 = width(0, 'STATUS');
660	  const w1 = width(1, 'CHECK');
661	  const line = (a: string, b: string, c: string) => `  ${a.padEnd(w0)}  ${b.padEnd(w1)}  ${c}`;
662	  const failed = report.checks.filter((c) => c.status === 'fail').length;
663	  const warned = report.checks.filter((c) => c.status === 'warn').length;
664	  return [
665	    'GraphGoblin preflight',
666	    '',
667	    line('STATUS', 'CHECK', 'DETAIL'),
668	    ...rows.map((r) => line(r[0], r[1], r[2])),
669	    '',
670	    `${String(failed)} failed, ${String(warned)} warning(s): ${
671	      report.ok ? 'ready to start' : 'fix the failed checks before starting'
672	    }`,
673	    '',
674	  ].join('\n');
675	}
676	
677	export interface PreflightCliOptions extends ConfigPreflightOptions {
678	  env?: NodeJS.ProcessEnv;
679	  write?: (text: string) => void;
680	}
681	
682	/** `graphgoblin-api --preflight`: print the checks and return the exit code (0 unless a check failed). */
683	export async function runPreflightCli(options: PreflightCliOptions = {}): Promise<number> {
684	  const write = options.write ?? ((text: string) => process.stdout.write(text));
685	  let config: ApiConfig;
686	  try {
687	    config = loadConfig(options.env ?? process.env);
688	  } catch (error) {
689	    write(`GraphGoblin preflight\n\n  FAIL  configuration  ${message(error)}\n`);
690	    return 1;
691	  }
692	  const sources = await configPreflightSources(config, options);
693	  try {
694	    const report = await runPreflight(sources);
695	    write(formatPreflight(report));
696	    return report.ok ? 0 : 1;
697	  } finally {
698	    sources.close();
699	  }
700	}
