    const secretsFor = (ownerId: string): SqliteSecrets =>
      new SqliteSecrets(db, clock, masterKey, ownerId);
    const timers = new TimerService(new SqliteTimerStore(db), clock, {
      pollIntervalMs: config.timerPollMs,
