  harnesses: overrides.harnesses ?? {
    codex: codex.harness,
    claude: new ClaudeHarness({
      ...(config.claudeBinary ? { binary: config.claudeBinary } : {}),
    }),
    ollama: ollama.harness,
  },
  modelCatalog: catalog,
  // LLM evaluation uses Codex; all classifier primitives use the owner registry.
  deciders: overrides.deciders ?? [new CodexDecider(structured)],
  classifiers: overrides.classifiers ?? classifierRegistry,
  structured,
  scripts: processScripts,
  workspace: ownedResources.workspace,
  timers,
  probes: overrides.probes ?? new HttpProbes(),
  delivery: createReturnDelivery({
    webhooks: new HttpWebhookDelivery(clock),
    logger,
  }),
  artifacts: ownedResources.artifacts,
  secrets: ownerSecrets,
};
const voice = new VoiceService(
  {
    config,
    masterKey,
    repos: { settings: settingsRepo, secretsFor, loops, chat, runs },
    ports,
  },
  processScripts,
);
ports.scripts = new VoiceScripts(processScripts, voice);
const templateCatalog = new TemplateCatalog(
  overrides.templateCatalogRoot ??
    fileURLToPath(
      new URL(import.meta.url.endsWith('.ts') ? '../templates' : './catalog', import.meta.url),
    ),
);
const templates = { catalog: templateCatalog };
const settings: EngineSettings = {
  defaults: config.defaults,
  maxConcurrentRuns: config.maxConcurrentRuns,
  // Harness-scoped Settings defaults are read at run start; GG_DEFAULTS are the fallback.
  ownerDefaults: (ownerId) => readOwnerDefaults(settingsRepo, ownerId),
};
const manager = new RunManager(ports, settings);
const polls = new PollTriggers({
  probes: ports.probes,
  scripts: ports.scripts,
  manager,
  hasDedupe: (loopId, nodeId, key) => runs.hasTriggerDedupe(loopId, nodeId, key),
  findSeen: (loopId, nodeId, keys) => runs.findTriggerDedupeKeys(loopId, nodeId, keys),
  clock,
  logger,
  scriptCwd: config.dataDir,
  tickMs: config.timerPollMs,
});
const triggers = new TriggerService({
  loops,
  runs,
  schedules,
  endpoints,
  inbound,
  manager,
  eventAdmission: ports.admission.events,
  cron,
  secretsFor,
  clock,
  ids,
  logger,
  webhookRateLimit: config.hookRateLimitPerMinute,
  polls,
});

const prepareShutdown = (): void => {
  voice.stop();
  void stopOllama().catch(() => logger.warn({}, 'Ollama discovery could not stop cleanly'));
  void historyCleanup.stop();
  admissionClosed = true;
  manager.closeIndependentAdmission();
  cron.stop();
  polls.stop();
  triggers.stop();
};
const shutdown = new ShutdownController(
  manager,
  config.shutdownGraceMs,
  prepareShutdown,
  logger,
);
let starting: Promise<void> | undefined;
let stopping: Promise<void> | undefined;
let disposing: Promise<void> | undefined;
const dispose = (): Promise<void> => {
  disposing ??= (async () => {
    clearInterval(audioTimer);
    await audioCleaning?.catch(() => undefined);
    await chatAudio.close();
    await voice.close();
    await stopOllama();
    await historyCleanup.stop();
    cron.stop();
    polls.stop();
    triggers.stop();
    timers.stop();
    manager.stop();
    await manager.waitForWebhookRecovery();
    await manager.waitForIdle();
    try {
      handle.close();
    } finally {
      try {
        await databaseLock?.release();
      } finally {
        await lock.release();
      }
      shutdown.stopped();
    }
  })();
  return disposing;
};
const stop = (): Promise<void> => {
  stopping ??= (async () => {
    // Direct callers may stop during migration or recovery. Keep ownership until startup
    // finishes, then shut down; otherwise a new owner could recover while this one starts.
    if (starting && !disposing) prepareShutdown();
    await starting?.catch(() => undefined);
    if (starting && !disposing) await shutdown.drain();
    await dispose();
  })();
  return stopping;
};

const finalizeResources = (): Promise<void> => {
  stopping ??= (async () => {
    // Resource closure also serializes with startup; it never releases a migrating store.
    await starting?.catch(() => undefined);
    await dispose();
  })();
  return stopping;
};

return {
  ollama,
  chatAudio,
  voice,
  historyCleanup,
  templates,
  config,
  handle,
  ports,
  settings,
  manager,
  timers,
  cron,
  triggers,
  polls,
  masterKey,
  classifierRegistry,
  repos: {
    deletionEligibility: new SqliteDeletionEligibility(db),
    runs,
    loops,
    sessions,
    events,
    settings: settingsRepo,
    apiKeys,
    chat,
    catalog,
    classifiers,
    schedules,
    endpoints,
    inbound,
    secretsFor,
  },
  async onSecretChanged(ownerId, name) {
    for (const hook of secretHooks) await hook(ownerId, name);
  },
  onClassifierChanged(ownerId, id) {
    classifierRegistry.invalidate(ownerId, id);
    return Promise.resolve();
  },
  start() {
    if (stopping) return Promise.reject(new Error('container has been stopped'));
    starting ??= (async () => {
      try {
        await handle
          .migrate({
            skipDefinitionValidation: preflightProtected && startupReadiness === 'current',
          })
          .catch(refuseStore);
        await classifiers.seedBuiltin(LOCAL_OWNER, BUILTIN_CLASSIFIER);
        if (config.jevApiKey && (await ownerSecrets.resolve(JEV_SECRET)) === undefined) {
          await ownerSecrets.set(JEV_SECRET, config.jevApiKey.value);
          logger.info({}, `seeded jev-api-key from ${config.jevApiKey.source}`);
        }
        await catalog.seed();
        await chat.ensureGateway(
          LOCAL_OWNER,
          createSystemChatDefinition({
            name: 'Gateway chat',
            harness: selectSystemChatHarness({
              ownerDefaults: await readOwnerDefaults(settingsRepo, LOCAL_OWNER),
              processDefaults: config.defaults,
            }),
          }),
        );
        await chat.recoverAudioReservations();
        await cleanupAudio(true);
        if (!admissionClosed) ollama.start();
        if (overrides.startTimers !== false) {
          audioTimer = setInterval(() => {
            void cleanupAudio().catch(() =>
              logger.warn({}, 'chat audio cleanup could not finish'),
            );
          }, 60_000);
          audioTimer.unref();
        }
        await manager.start();
        await historyCleanup.start(overrides.startTimers !== false);
        if (!admissionClosed) {
          triggers.start();
          await triggers.armAll();
        }
        if (overrides.startTimers !== false) {
          timers.start();
          if (!admissionClosed) await cron.start();
          if (!admissionClosed) polls.start();
          else cron.stop();
        }
      } catch (error) {
        await dispose();
        throw error;
      }
    })();
    return starting;
  },
  dispose: finalizeResources,
  prepareShutdown,

