      exists: true,
      withWal,
      schemaHash,
      dataHash,
      logicalHash: sha(schemaHash + dataHash),
      tableCount: tables.length,
      perTable,
      catalog,
      catalogCount: catalog?.length ?? null,
      catalogHash: catalog ? sha(JSON.stringify(catalog)) : null,
      migrations,
