// ------------------------------------------------------------------ CLI preflight case
async function preflightCase(id, purpose, { dbFile, dataDir, dbUrl, defaults, expectExit, expectRows, watchDirs, variant, expectAbsent = [] }) {
  const c = newCase(id, 'built-cli-preflight', purpose, { variant, defaults });
