function logical(dbFile, { withWal = true } = {}) {
  if (!existsSync(dbFile)) return { exists: false };
  const dir = join(ROOT, 'measure', String(++measureSeq).padStart(4, '0'));
  mkdirSync(dir, { recursive: true });
