if (existsSync(FAKE_LOG)) copyFileSync(FAKE_LOG, join(RAW, 'fake-cli-invocations.jsonl'));
writeFileSync(join(RAW, 'ollama-recorder-requests.json'), JSON.stringify(ollamaRequests, null, 2) + '\n');
