      for (const f of pending) {
        try {
          unlinkSync(f);
          out.push({ delayMs: delay, file: basename(f), ok: true });
        } catch (error) {
          out.push({ delayMs: delay, file: basename(f), ok: false, code: error.code });
        }
      }
