/**
 * Strict for an existing WAL: byte-identical. For a store with no WAL file, SQLite's read-only
 * WAL-mode open may create an empty one (run-01 finding): require zero bytes (no frames, nothing
 * persisted) and record the creation explicitly as `walCreatedEmpty` instead of hiding it.
 */
function walChecks(c, b, a) {
  if (b['-wal']) {
    check(c, 'existing WAL bytes unchanged (no checkpoint, no frames)', b['-wal'], a['-wal']);
  } else {
    check(c, 'no WAL frames written (WAL still absent, or created with 0 bytes)', true, a['-wal'] === null || a['-wal']?.size === 0);
    c.walCreatedEmpty = a['-wal'] !== null && a['-wal']?.size === 0;
    c.checks.push({
      name: 'FINDING (recorded, see M05): 0-byte -wal file created where none existed',
      expected: 'recorded',
      actual: c.walCreatedEmpty,
      pass: true,
      observation: true,
    });
  }
}

