import { DatabaseSync } from 'node:sqlite';

const REPO = 'G:\\ggq\\gg-i4-448-qa\\GraphGoblin';
const Q = 'C:\\Users\\98jak\\graphgoblin-qa\\2026-11-17-five-intents\\i4-448-independent-01';
const RUN_LABEL = process.argv[2] ?? 'run-01';
