// M05: isolate the run-01 empty -wal finding from the #448 projection. None of these paths call
// projectStartupModelCatalog; store-format.ts/db.ts are unchanged between base and candidate.
{
  const c = newCase('M05', 'native-isolation-probe', 'which read-only open creates a 0-byte -wal on a store that has none (no projection involved)');
  c.probes = [];
  const probe = async (label, open) => {
    const file = place(variants.golden, join(ROOT, 'cases', 'M05', label.replace(/[^a-z0-9]+/gi, '-'), 'gateway.db'));
    const before = fileFacts(file);
    const beforeLogical = logical(file);
    let outcome;
    try {
      outcome = await open(file);
    } catch (error) {
      outcome = { error: String(error) };
    }
    const after = fileFacts(file);
    const afterLogical = logical(file);
    c.probes.push({ label, outcome, before, after });
    check(c, `${label}: DB bytes unchanged`, before.db, after.db);
    check(c, `${label}: logical hash unchanged`, beforeLogical.logicalHash, afterLogical.logicalHash);
    check(c, `${label}: no WAL frames (absent or 0 bytes)`, true, after['-wal'] === null || after['-wal']?.size === 0);
    c.checks.push({ name: `${label}: observed -wal/-shm after (recorded)`, expected: 'recorded', actual: { wal: after['-wal'], shm: after['-shm'] }, pass: true, observation: true });
    return after;
  };
  await probe('built openReadOnlyDatabaseClient SELECT', async (file) => {
    const client = infra.openReadOnlyDatabaseClient(file);
    try {
      return { rows: (await client.execute('SELECT COUNT(*) AS n FROM model_catalog')).rows.length };
    } finally {
      client.close();
    }
  });
  await probe('built guardCurrentStore only (shared startup and preflight guard)', async (file) => {
    const client = infra.openReadOnlyDatabaseClient(file);
    try {
      return { state: await infra.guardCurrentStore(client) };
    } finally {
      client.close();
    }
  });
  await probe('node sqlite readOnly SELECT (independent SQLite)', async (file) => {
    const db = new DatabaseSync(file, { readOnly: true });
    try {
      return { n: db.prepare('SELECT COUNT(*) AS n FROM model_catalog').get().n };
    } finally {
      db.close();
    }
  });
  finish(c);
}

// ------------------------------------------------------------------ wrap-up
ollama.close();

