  c.port = port;
  const deadline = Date.now() + 120_000;
  let listening = false;
  while (Date.now() < deadline) {
    if (p.exit) break;
    if (p.stdout.includes('"msg":"GraphGoblin API listening"')) {
      listening = true;
      break;
    }
    await sleep(100);
  }
  if (!listening && !p.exit) {
