    for (const name of readdirSync(d).sort()) {
      const path = join(d, name);
      const s = statSync(path);
      const rel = relative(dir, path).replaceAll('\\', '/');
      out.push(s.isDirectory() ? `${rel}/` : `${rel} (${s.size})`);
      if (s.isDirectory() && depth < 4) walk(path, depth + 1);
