const HOME = join(ROOT, 'home');
for (const d of [HOME, join(HOME, 'AppData', 'Roaming'), join(HOME, 'AppData', 'Local'), join(ROOT, 'tmp')])
  mkdirSync(d, { recursive: true });

function childEnv(extra) {
