}

// M05: isolate the run-01 empty -wal finding from the #448 projection. None of these paths call
// projectStartupModelCatalog; store-format.ts/db.ts are unchanged between base and candidate.
{
  const c = newCase('M05', 'native-isolation-probe', 'which read-only open creates a 0-byte -wal on a store that has none (no projection involved)');
